(function(root){
const field=(id,label,type='textarea',required=true,description='',options=[])=>({id,label,type,required,description,options});
function preset(kind){return kind==='feature'?{name:'Feature request',description:'Suggest an improvement to this project',title:'[Feature]: ',fields:[field('problem','What problem would this solve?'),field('solution','Describe your proposed solution'),field('alternatives','What alternatives have you considered?','textarea',false)]}:{name:'Bug report',description:'Report a reproducible problem',title:'[Bug]: ',fields:[field('summary','What happened?','textarea',true,'Describe the problem and its impact.'),field('steps','Steps to reproduce','textarea',true,'List the exact steps so someone else can reproduce this.'),field('expected','What did you expect to happen?'),field('version','Version','input',true,'For example: 1.0.0'),field('environment','Environment','dropdown',true,'Choose the closest match.',['Windows','macOS','Linux','Other'])]};}
function validate(s){let e=[];if(!s.name.trim())e.push('Give your template a name.');if(!s.description.trim())e.push('Add a template description.');if(!s.fields.length)e.push('Add at least one question.');let ids=new Set(),labels=new Set();s.fields.forEach((f,i)=>{if(!f.label.trim())e.push(`Question ${i+1} needs a label.`);if(!/^[a-zA-Z0-9_-]+$/.test(f.id)||ids.has(f.id))e.push(`Question ${i+1} needs a unique valid ID.`);ids.add(f.id);if(labels.has(f.label.trim()))e.push('Question labels must be unique.');labels.add(f.label.trim());if(['dropdown','checkboxes'].includes(f.type)&&(!f.options.length||f.options.some(o=>!o.trim())||new Set(f.options).size!==f.options.length))e.push(`Question ${i+1} needs distinct, nonempty choices.`);});return e;}
function yaml(s){const q=JSON.stringify;let lines=[`name: ${q(s.name)}`,`description: ${q(s.description)}`,`title: ${q(s.title)}`,'body:'];for(const f of s.fields){lines.push(`  - type: ${f.type}`,`    id: ${q(f.id)}`,'    attributes:',`      label: ${q(f.label)}`);if(f.description)lines.push(`      description: ${q(f.description)}`);if(['dropdown','checkboxes'].includes(f.type)){lines.push('      options:');for(const o of f.options){lines.push(f.type==='checkboxes'?`        - label: ${q(o)}`:`        - ${q(o)}`);if(f.type==='checkboxes')lines.push(`          required: ${!!f.required}`);}}if(f.type!=='checkboxes')lines.push('    validations:',`      required: ${!!f.required}`);}return lines.join('\n')+'\n';}
const api={preset,validate,yaml};if(typeof module!=='undefined')module.exports=api;else root.IssueCraft=api;
})(globalThis);
